use super::*;
struct Record{id:Option<String>,payload:Option<Vec<u8>>}
fn observe<T>(operation:impl FnOnce()->T)->(T,usize,usize){crate::test_allocation::observe_backing(operation)}
fn receive_receipt<T>(owner:&mut RetainedHistoryRecords<T>,grant:RetainedCloneGrant,born:usize,released:usize){let(received,progress)=owner.take_receipt().unwrap();assert_eq!(received,grant);assert!(progress.fits(grant));assert_eq!(progress.copied_bytes,0);assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));}
fn close_record(record:&mut Record,grant:RetainedCloneGrant){
 let(result,born,released)=observe(||::protocol::codec::RetainedWireFieldDecode::admit_received_text(&mut record.id,grant).unwrap());assert_eq!((born,released),(0,0));let mut id=result.unwrap();assert_eq!(id.take_receipt().unwrap(),(grant,RetainedCloneProgress{copied_items:1,..Default::default()}));let(_,born,released)=observe(||id.close_step(grant).unwrap());let(received,progress)=id.take_receipt().unwrap();assert_eq!(received,grant);assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));assert!(progress.fits(grant));assert!(id.terminal_is_empty());
 let(result,born,released)=observe(||::protocol::codec::RetainedWireFieldDecode::admit_received(&mut record.payload,grant).unwrap());assert_eq!((born,released),(0,0));let mut payload=result.unwrap();assert_eq!(payload.take_receipt().unwrap(),(grant,RetainedCloneProgress{copied_items:1,..Default::default()}));let(_,born,released)=observe(||payload.close_step(grant).unwrap());let(received,progress)=payload.take_receipt().unwrap();assert_eq!(received,grant);assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));assert!(progress.fits(grant));assert!(payload.terminal_is_empty());
}

#[test]
fn original_history_record_native_vector_growth_preserves_payloads_and_paid_receiving_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["grant"];let axis=|key:&str|p[key].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:axis("items"),maximum_copy_bytes:axis("copy"),maximum_capacity_bytes:axis("capacity"),maximum_release_bytes:axis("release"),maximum_depth:axis("depth")};
 for cancellation in [0,1,2,3,16]{
  let mut original:Vec<Option<Record>>=law["records"].as_array().unwrap().iter().map(|record|Some(Record{id:Some(record["id"].as_str().unwrap().to_owned()),payload:Some(record["payload"].as_str().unwrap().as_bytes().to_vec())})).collect();let pointers:Vec<_>=original.iter().map(|record|{let record=record.as_ref().unwrap();(record.id.as_ref().unwrap().as_ptr(),record.payload.as_ref().unwrap().as_ptr())}).collect();
  for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,born,released)=observe(||RetainedHistoryRecords::<Record>::admit(denied).unwrap());assert!(result.is_none());assert_eq!((born,released),(0,0));}
  let(result,born,released)=observe(||RetainedHistoryRecords::<Record>::admit(grant).unwrap());assert_eq!((born,released),(0,0));let mut owner=result.unwrap();receive_receipt(&mut owner,grant,born,released);let(mut births,mut releases,mut index)=(0,0,0);
  for _ in 0..cancellation{
   if index==original.len(){break}let(demand,born,released)=observe(||owner.demands().unwrap());assert_eq!((born,released),(0,0));for(axis,denied)in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant}].into_iter().enumerate(){if(axis==2&&demand.capacity_bytes==0)||(axis==3&&demand.release_bytes==0){continue}let(step,born,released)=observe(||owner.append_original(&mut original[index],denied).unwrap());assert_eq!(step,RetainedHistoryRecordsStep::Blocked);assert_eq!((born,released),(0,0));assert_eq!(original[index].as_ref().unwrap().id.as_ref().unwrap().as_ptr(),pointers[index].0);assert!(owner.receipt().is_none());}
   let(step,born,released)=observe(||owner.append_original(&mut original[index],grant).unwrap());births+=born;releases+=released;assert!(matches!(step,RetainedHistoryRecordsStep::Reserved|RetainedHistoryRecordsStep::Published));if step==RetainedHistoryRecordsStep::Reserved{assert!(original[index].is_some())}else{assert!(original[index].is_none());let record=owner.records().last().unwrap();assert_eq!(record.id.as_ref().unwrap().as_ptr(),pointers[index].0);assert_eq!(record.payload.as_ref().unwrap().as_ptr(),pointers[index].1);index+=1;}let mut absent=None;let(step,denied_birth,denied_release)=observe(||owner.append_original(&mut absent,grant).unwrap());assert_eq!(step,RetainedHistoryRecordsStep::Blocked);assert_eq!((denied_birth,denied_release),(0,0));receive_receipt(&mut owner,grant,born,released);
  }
  if cancellation==16{assert_eq!(index,original.len());let pointer=owner.records().as_ptr();let mut receiver=None;let(step,born,released)=observe(||owner.take_ready_into(&mut receiver,grant).unwrap());assert_eq!(step,RetainedHistoryRecordsStep::Closed);assert_eq!((born,released),(0,0));receive_receipt(&mut owner,grant,born,released);assert!(owner.terminal_is_empty());assert_eq!(receiver.as_ref().unwrap().as_ptr(),pointer);let(result,born,released)=observe(||RetainedHistoryRecords::admit_original_index(&mut receiver,grant).unwrap());assert_eq!((born,released),(0,0));assert!(receiver.is_none());owner=result.unwrap();receive_receipt(&mut owner,grant,born,released);assert_eq!(owner.records().as_ptr(),pointer);}
  owner.cancel();while !owner.records().is_empty(){let target=owner.records().len()-1;let(step,born,released)=observe(||owner.take_original_into(&mut original[target],grant).unwrap());assert_eq!(step,RetainedHistoryRecordsStep::Returned);assert_eq!((born,released),(0,0));receive_receipt(&mut owner,grant,born,released);let record=original[target].as_ref().unwrap();assert_eq!(record.id.as_ref().unwrap().as_ptr(),pointers[target].0);assert_eq!(record.payload.as_ref().unwrap().as_ptr(),pointers[target].1);}
  let demand=owner.demands().unwrap();for(axis,denied)in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant}].into_iter().enumerate(){if axis==2&&demand.release_bytes==0{continue}let(step,born,released)=observe(||owner.close_step(denied).unwrap());assert_eq!(step,RetainedHistoryRecordsStep::Blocked);assert_eq!((born,released),(0,0));}
  let(step,born,released)=observe(||owner.close_step(grant).unwrap());assert_eq!(step,RetainedHistoryRecordsStep::Closed);births+=born;releases+=released;receive_receipt(&mut owner,grant,born,released);assert!(owner.terminal_is_empty());assert_eq!(births,releases);let(_,born,released)=observe(||drop(owner));assert_eq!((born,released),(0,0));for record in &mut original{close_record(record.as_mut().unwrap(),grant)}
 }
 eprintln!("[DEBUG] original typed History records preserve native payload pointers through separately paid vector growth, publish, ready transfer, original receiving admission, partial return and physical release; metadata copy0 and every heap receipt exact");
}
